detaileddescription.para:
Example usage: FGFDMExec*FDMExec=newFGFDMExec();

FGInitialCondition*fgic=newFGInitialCondition(FDMExec);
FGTrimfgt(FDMExec,fgic,tFull);
fgic->SetVcaibratedKtsIC(100);
fgic->SetAltitudeFtIC(1000);
fgic->SetClimbRate(500);
if(!fgt.DoTrim()){
std::cout<<"TrimFailed"<<std::endl;
}
fgt.Report();
